    --safe-bottom: env(safe-area-inset-bottom, 0px);
    --safe-left: env(safe-area-inset-left, 0px);
    --safe-right: env(safe-area-inset-right, 0px);

    /* Per-project accent theme. `--accent`/`--accent-on` are RGB triplets so
       Tailwind's `rgb(var(--accent) / <alpha-value>)` opacity modifiers (e.g.
       `bg-primary/20`) compile to valid CSS. `--accent-hex` is the raw hex for
       SVG/`var()` consumers (e.g. BrandMark) that cannot read a triplet.
       These are overridden at runtime from the active project's accentColor. */
